scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('selectbox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('selectbox1_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('selectbox1_label').textContent == 'a3'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "log", "selectbox2 value : nullselectbox2 getSelectedIndex ==: 0");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");

    WebSquare.wUnit.addCommand("assert", "log1", "selectbox4 value : nullselectbox4 getSelectedIndex ==: 0");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

